void GridMapFusionNode::onGridMap(
  const nav_msgs::msg::OccupancyGrid::ConstSharedPtr & occupancy_grid_msg,
  const std::string & topic_name)
{
  std::unique_ptr<ScopedTimeTrack> st_ptr;
  if (time_keeper_) st_ptr = std::make_unique<ScopedTimeTrack>(__func__, *time_keeper_);

  std::lock_guard<std::mutex> lock(mutex_);
  const bool is_already_subscribed_this = (gridmap_dict_[topic_name] != nullptr);
  const bool is_already_subscribed_tmp = std::any_of(
    std::begin(gridmap_dict_tmp_), std::end(gridmap_dict_tmp_),
    [](const auto & e) { return e.second != nullptr; });

  // already subscribed
  if (is_already_subscribed_this) {
    gridmap_dict_tmp_[topic_name] = occupancy_grid_msg;

    if (!is_already_subscribed_tmp) {
      auto period = std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::duration<double>(timeout_sec_));
      try {
        setPeriod(period.count());
      } catch (rclcpp::exceptions::RCLError & ex) {
        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "%s", ex.what());
      }
      timer_->reset();
    }
    // first time to subscribe in this period
  } else {
    gridmap_dict_[topic_name] = occupancy_grid_msg;  // add to buffer

    // check if all topics are subscribed
    bool is_subscribed_all = std::all_of(
      std::begin(gridmap_dict_), std::end(gridmap_dict_),
      [](const auto & e) { return e.second != nullptr; });
    // Then, go to publish
    if (is_subscribed_all) {
      for (const auto & e : gridmap_dict_tmp_) {
        if (e.second != nullptr) {
          gridmap_dict_[e.first] = e.second;
        }
      }
      std::for_each(std::begin(gridmap_dict_tmp_), std::end(gridmap_dict_tmp_), [](auto & e) {
        e.second = nullptr;
      });

      timer_->cancel();
      publish();
      // if not all topics are subscribed, set timer
    } else if (offset_map_.size() > 0) {
      timer_->cancel();
      auto period = std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::duration<double>(timeout_sec_ - offset_map_[topic_name]));
      try {
        setPeriod(period.count());
      } catch (rclcpp::exceptions::RCLError & ex) {
        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "%s", ex.what());
      }
      timer_->reset();
    }
  }
}

void GridMapFusionNode::publish()
{
  std::unique_ptr<ScopedTimeTrack> st_ptr;
  if (time_keeper_) st_ptr = std::make_unique<ScopedTimeTrack>(__func__, *time_keeper_);

  stop_watch_ptr_->toc("processing_time", true);
  builtin_interfaces::msg::Time latest_stamp = get_clock()->now();
  double height = 0.0;

  // merge available gridmap
  std::vector<OccupancyGridMapFixedBlindSpot> subscribed_maps;
  std::vector<double> weights;
  {  // merging grid map
    std::unique_ptr<ScopedTimeTrack> inner_st_ptr;
    if (time_keeper_)
      inner_st_ptr = std::make_unique<ScopedTimeTrack>("merge_grid_map", *time_keeper_);

    for (const auto & e : gridmap_dict_) {
      if (e.second != nullptr) {
        subscribed_maps.push_back(GridMapFusionNode::OccupancyGridMsgToGridMap(*e.second));
        weights.push_back(input_topic_weights_map_[e.first]);
        latest_stamp = e.second->header.stamp;
        height = e.second->info.origin.position.z;
      }
    }
  }

  // return if empty
  if (subscribed_maps.empty()) {
    RCLCPP_WARN_THROTTLE(
      get_logger(), *get_clock(), 5000,
      "No grid map is subscribed. Please check the topic name and the topic type.");
    return;
  }

  // fusion map
  // single frame gridmap fusion
  auto & fused_map = SingleFrameOccupancyFusion(subscribed_maps, latest_stamp, weights);
  // multi frame gridmap fusion
  occupancy_grid_map_updater_ptr_->update(fused_map);

  // publish
  fused_map_pub_->publish(
    OccupancyGridMapToMsgPtr(map_frame_, latest_stamp, height, *occupancy_grid_map_updater_ptr_));
  single_frame_pub_->publish(OccupancyGridMapToMsgPtr(map_frame_, latest_stamp, height, fused_map));

  // copy 2nd temp to temp buffer
  gridmap_dict_ = gridmap_dict_tmp_;
  std::for_each(std::begin(gridmap_dict_tmp_), std::end(gridmap_dict_tmp_), [](auto & e) {
    e.second = nullptr;
  });

  // add processing time for debug
  if (debug_publisher_ptr_ && stop_watch_ptr_) {
    const double cyclic_time_ms = stop_watch_ptr_->toc("cyclic_time", true);
    const double processing_time_ms = stop_watch_ptr_->toc("processing_time", true);
    const double pipeline_latency_ms =
      std::chrono::duration<double, std::milli>(
        std::chrono::nanoseconds((this->get_clock()->now() - latest_stamp).nanoseconds()))
        .count();
    debug_publisher_ptr_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/cyclic_time_ms", cyclic_time_ms);
    debug_publisher_ptr_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/processing_time_ms", processing_time_ms);
    debug_publisher_ptr_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
      "debug/pipeline_latency_ms", pipeline_latency_ms);
  }
}

const OccupancyGridMapFixedBlindSpot & GridMapFusionNode::SingleFrameOccupancyFusion(
  std::vector<OccupancyGridMapFixedBlindSpot> & occupancy_grid_maps,
  const builtin_interfaces::msg::Time latest_stamp, const std::vector<double> & weights)
{
  std::unique_ptr<ScopedTimeTrack> st_ptr;
  if (time_keeper_) st_ptr = std::make_unique<ScopedTimeTrack>(__func__, *time_keeper_);

  // if only single map
  if (occupancy_grid_maps.size() == 1) {
    return occupancy_grid_maps[0];
  }

  // get map to gridmap_origin_frame_ transform
  Pose gridmap_origin{};
  try {
    gridmap_origin = utils::getPose(latest_stamp, tf_buffer_, gridmap_origin_frame_, map_frame_);
  } catch (tf2::TransformException & ex) {
    RCLCPP_WARN_STREAM(get_logger(), ex.what());
    return occupancy_grid_maps[0];
  }

  {  // create fused occupancy grid map
    std::unique_ptr<ScopedTimeTrack> inner_st_ptr;
    if (time_keeper_)
      inner_st_ptr = std::make_unique<ScopedTimeTrack>("create_fused_map", *time_keeper_);

    if (
      !fused_map_ || fused_map_->getSizeInCellsX() != occupancy_grid_maps[0].getSizeInCellsX() ||
      fused_map_->getSizeInCellsY() != occupancy_grid_maps[0].getSizeInCellsY() ||
      fused_map_->getResolution() != occupancy_grid_maps[0].getResolution()) {
      fused_map_ = std::make_unique<OccupancyGridMapFixedBlindSpot>(
        false, occupancy_grid_maps[0].getSizeInCellsX(), occupancy_grid_maps[0].getSizeInCellsY(),
        occupancy_grid_maps[0].getResolution());
    }

    // init fused map with calculated origin
    fused_map_->resetMaps();

    fused_map_->updateOrigin(
      gridmap_origin.position.x - fused_map_->getSizeInMetersX() / 2,
      gridmap_origin.position.y - fused_map_->getSizeInMetersY() / 2);

    // fix origin of each map
    for (auto & map : occupancy_grid_maps) {
      map.updateOrigin(fused_map_->getOriginX(), fused_map_->getOriginY());
    }

    // assume map is same size and resolutions
    for (unsigned int x = 0; x < fused_map_->getSizeInCellsX(); x++) {
      for (unsigned int y = 0; y < fused_map_->getSizeInCellsY(); y++) {
        // get cost of each map
        std::vector<unsigned char> costs;
        for (auto & map : occupancy_grid_maps) {
          costs.push_back(map.getCost(x, y));
        }

        // set fusion policy
        auto fused_cost = fusion_policy::singleFrameOccupancyFusion(costs, fusion_method_, weights);

        // set max cost to fused map
        fused_map_->setCost(x, y, fused_cost);
      }
    }

    return *fused_map_;
  }  // scope for time keeper ends
}

geometry_msgs::msg::Pose getPose(
  const builtin_interfaces::msg::Time & stamp, const tf2_ros::Buffer & tf2,
  const std::string & source_frame, const std::string & target_frame)
{
  geometry_msgs::msg::Pose pose;
  geometry_msgs::msg::TransformStamped tf_stamped;
  tf_stamped =
    tf2.lookupTransform(target_frame, source_frame, stamp, rclcpp::Duration::from_seconds(0.5));
  pose = autoware_utils::transform2pose(tf_stamped.transform);
  return pose;
}

geometry_msgs::msg::Pose transform2pose(const geometry_msgs::msg::Transform & transform)
{
  geometry_msgs::msg::Pose pose;
  pose.position.x = transform.translation.x;
  pose.position.y = transform.translation.y;
  pose.position.z = transform.translation.z;
  pose.orientation = transform.rotation;
  return pose;
}

void OccupancyGridMapInterface::updateOrigin(double new_origin_x, double new_origin_y) {
  // project the new origin into the grid
  int cell_ox{static_cast<int>(std::floor((new_origin_x - origin_x_) / resolution_))};
  int cell_oy{static_cast<int>(std::floor((new_origin_y - origin_y_) / resolution_))};

  // compute the associated world coordinates for the origin cell
  // because we want to keep things grid-aligned
  double new_grid_ox{origin_x_ + cell_ox * resolution_};
  double new_grid_oy{origin_y_ + cell_oy * resolution_};

  // To save casting from unsigned int to int a bunch of times
  int size_x{static_cast<int>(size_x_)};
  int size_y{static_cast<int>(size_y_)};

  // we need to compute the overlap of the new and existing windows
  int lower_left_x{std::min(std::max(cell_ox, 0), size_x)};
  int lower_left_y{std::min(std::max(cell_oy, 0), size_y)};
  int upper_right_x{std::min(std::max(cell_ox + size_x, 0), size_x)};
  int upper_right_y{std::min(std::max(cell_oy + size_y, 0), size_y)};

  unsigned int cell_size_x = upper_right_x - lower_left_x;
  unsigned int cell_size_y = upper_right_y - lower_left_y;

  // we need a map to store the obstacles in the window temporarily
  std::vector<unsigned char> local_map;

// #ifdef USE_CUDA
  using autoware::occupancy_grid_map::utils::copyMapRegionLaunch;
  if (use_cuda_) {
    copyMapRegionLaunch(
      device_costmap_.get(), lower_left_x, lower_left_y, size_x_, size_y_,
      device_costmap_aux_.get(), 0, 0, cell_size_x, cell_size_y, cell_size_x, cell_size_y, stream_);

    cudaMemsetAsync(
      device_costmap_.get(), cost_value::NO_INFORMATION, size_x_ * size_y_ * sizeof(std::uint8_t),
      stream_);
// #else
//   if (use_cuda_) 
//     RCLCPP_ERROR(
//       rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
//       "The code was compiled without cuda.");
//     return;
// #endif
  } else {
    local_map.resize(static_cast<size_t>(cell_size_x) * static_cast<size_t>(cell_size_y));

    // copy the local window in the costmap to the local map
    copyMapRegion(
      costmap_, lower_left_x, lower_left_y, size_x_, local_map.data(), 0, 0, cell_size_x,
      cell_size_x, cell_size_y);

    // now we'll set the costmap to be completely unknown if we track unknown space
    nav2_costmap_2d::Costmap2D::resetMaps();
  }

  // update the origin with the appropriate world coordinates
  origin_x_ = new_grid_ox;
  origin_y_ = new_grid_oy;

  // compute the starting cell location for copying data back in
  int start_x{lower_left_x - cell_ox};
  int start_y{lower_left_y - cell_oy};

  if (first_iteration_) {
    origin_x_ = new_grid_ox;
    origin_y_ = new_grid_oy;
    first_iteration_ = false;
    return;
  }

  // now we want to copy the overlapping information back into the map, but in its new location
// #ifdef USE_CUDA
  if (use_cuda_) {
    if (
      start_x < 0 || start_y < 0 || start_x + cell_size_x > size_x_ ||
      start_y + cell_size_y > size_y_) {
      RCLCPP_ERROR(
        rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
        "update coordinates are negative or out of bounds: start.x=%d, start.y=%d, cell_size.x=%d, "
        "cell_size.y=%d size_x:%d, size_y=%d",
        start_x, start_y, cell_size_x, cell_size_y, size_x_, size_y_);
      return;
    }

    copyMapRegionLaunch(
      device_costmap_aux_.get(), 0, 0, cell_size_x, cell_size_y, device_costmap_.get(), start_x,
      start_y, size_x_, size_y_, cell_size_x, cell_size_y, stream_);
// #else
//   if (use_cuda_) 
//     RCLCPP_ERROR(
//       rclcpp::get_logger("pointcloud_based_occupancy_grid_map"),
//       "The code was compiled without cuda.");
//     return;
// #endif
  } else {
    copyMapRegion(
      local_map.data(), 0, 0, cell_size_x, costmap_, start_x, start_y, size_x_, cell_size_x,
      cell_size_y);
  }
}

void copyMapRegionLaunch(
  const std::uint8_t * source_map, unsigned int sm_lower_left_x, unsigned int sm_lower_left_y,
  unsigned int sm_size_x, unsigned int sm_size_y, std::uint8_t * dest_map,
  unsigned int dm_lower_left_x, unsigned int dm_lower_left_y, unsigned int dm_size_x,
  unsigned int dm_size_y, unsigned int region_size_x, unsigned int region_size_y,
  cudaStream_t stream)
{
  const int threads_per_block = 256;
  const int num_blocks =
    (region_size_x * region_size_y + threads_per_block - 1) / threads_per_block;

  if (num_blocks == 0) {
    return;
  }

  copyMapRegionKernel<<<num_blocks, threads_per_block, 0, stream>>>(
    source_map, sm_lower_left_x, sm_lower_left_y, sm_size_x, sm_size_y, dest_map, dm_lower_left_x,
    dm_lower_left_y, dm_size_x, dm_size_y, region_size_x, region_size_y);
}

__global__ void copyMapRegionKernel(
  const std::uint8_t * source_map, unsigned int sm_lower_left_x, unsigned int sm_lower_left_y,
  unsigned int sm_size_x, unsigned int sm_size_y, std::uint8_t * dest_map,
  unsigned int dm_lower_left_x, unsigned int dm_lower_left_y, unsigned int dm_size_x,
  unsigned int dm_size_y, unsigned int region_size_x, unsigned int region_size_y)
{
  const int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= region_size_x * region_size_y) return;

  const int region_y = idx / region_size_x;
  const int region_x = idx % region_size_x;

  const int sm_index =
    sm_lower_left_y * sm_size_x + sm_lower_left_x + region_y * sm_size_x + region_x;
  const int dm_index =
    dm_lower_left_y * dm_size_x + dm_lower_left_x + region_y * dm_size_x + region_x;

  if (sm_index < sm_size_x * sm_size_y && dm_index < dm_size_x * dm_size_y) {
    dest_map[dm_index] = source_map[sm_index];
  }
}

virtual void resetMaps();

/**
 * @brief  Initializes the costmap, static_map, and markers data structures
 * @param size_x The x size to use for map initialization
 * @param size_y The y size to use for map initialization
 */
virtual void initMaps(unsigned int size_x, unsigned int size_y);

void copyMapRegion(
  data_type * source_map, unsigned int sm_lower_left_x,
  unsigned int sm_lower_left_y,
  unsigned int sm_size_x, data_type * dest_map, unsigned int dm_lower_left_x,
  unsigned int dm_lower_left_y, unsigned int dm_size_x, unsigned int region_size_x,
  unsigned int region_size_y)
{
  // we'll first need to compute the starting points for each map
  data_type * sm_index = source_map + (sm_lower_left_y * sm_size_x + sm_lower_left_x);
  data_type * dm_index = dest_map + (dm_lower_left_y * dm_size_x + dm_lower_left_x);

  // now, we'll copy the source map into the destination map
  for (unsigned int i = 0; i < region_size_y; ++i) {
    memcpy(dm_index, sm_index, region_size_x * sizeof(data_type));
    sm_index += sm_size_x;
    dm_index += dm_size_x;
  }
}

